   474          slen = decode_record(ctx, cursor, attr_dns_rr, p, end - p, packet_ctx, packet + 6);
   475          if (slen < 0) goto fail;
   476          p += slen;
   477
   478          slen = decode_record(ctx, cursor, attr_dns_ns, p, end - p, packet_ctx, packet + 8);
   479          if (slen < 0) goto fail;
   480          p += slen;
